svg.script:
/* Splooshi Scramjet adapter. Engine assets live beside index.svg on JSDelivr. */
const HTML_NS="http://www.w3.org/1999/xhtml";
const htmlEl=tag=>document.createElementNS(HTML_NS,tag);
const BASE_URL=new URL("./",location.href);
const PATHS={
 sw:new URL("sw.js",BASE_URL).href,
 bundle:new URL("scramjet.js",BASE_URL).href,
 wasm:new URL("scramjet.wasm",BASE_URL).href,
 utils:new URL("scramjet-utils.js",BASE_URL).href,
 api:new URL("controller.api.js",BASE_URL).href,
 inject:new URL("controller.inject.js",BASE_URL).href,
 swController:new URL("controller.sw.js",BASE_URL).href,
 libcurl:new URL("libcurl-client.js",BASE_URL).href
};
const Engine=(()=>{
 let state="idle",controller=null,utils=null,transport=null;
 const WISP="wss://wisp.mercurywork.shop/";
 const loadedScripts=new Set();
 function say(msg){diagLog("INFO",msg);console.info("[Splooshi]",msg)}
 function loadScript(src){
  if(loadedScripts.has(src)){diagLog("DEBUG","Engine script already loaded: "+new URL(src).pathname.split("/").pop());return Promise.resolve()}
  const asset=new URL(src).pathname.split("/").pop(),started=performance.now();
  diagLog("INFO","Loading engine script: "+asset);
  return new Promise((resolve,reject)=>{
   const s=htmlEl("script");s.src=src;s.async=false;
   s.onload=()=>{loadedScripts.add(src);diagLog("SUCCESS",`Loaded ${asset} in ${Math.round(performance.now()-started)} ms`);resolve()};
   s.onerror=()=>{const e=new Error("Could not load engine asset: "+asset);diagLog("ERROR",e.message);reject(e)};
   $("#svgRoot").appendChild(s);
  });
 }
 async function preflight(){
  diagLog("INFO","Checking required proxy files before starting Scramjet.");
  const need=[PATHS.sw,PATHS.bundle,PATHS.wasm,PATHS.utils,PATHS.api,PATHS.inject,PATHS.swController,PATHS.libcurl];
  const missing=[];
  for(const u of need){
   const name=new URL(u).pathname.split("/").pop(),started=performance.now(),aborter=new AbortController();
   const timeout=setTimeout(()=>aborter.abort(),12000);
   try{
    const r=await fetch(u,{cache:"no-store",signal:aborter.signal});
    const ct=(r.headers.get("content-type")||"").toLowerCase(),length=r.headers.get("content-length");
    let problem="";
    if(!r.ok||ct.includes("text/html"))problem=`HTTP ${r.status}${ct?`, content-type ${ct}`:""}`;
    else if(u===PATHS.wasm){const b=new Uint8Array(await r.arrayBuffer());if(!(b[0]===0&&b[1]===0x61&&b[2]===0x73&&b[3]===0x6d))problem="invalid WASM magic header";}
    if(problem){missing.push(name+(name==="scramjet.wasm"&&problem.includes("WASM")?" (invalid WASM file)":""));diagLog("ERROR",`Asset check failed: ${name} — ${problem}`)}
    else diagLog("SUCCESS",`Asset OK: ${name}${length?` (${length} bytes)`:""} in ${Math.round(performance.now()-started)} ms${ct?`; ${ct}`:""}`);
   }catch(e){missing.push(name);diagLog("ERROR",`Asset fetch failed: ${name} — ${e?.name==="AbortError"?"timed out after 12 seconds":diagFormat(e)}`)}finally{clearTimeout(timeout)}
  }
  if(missing.length)throw new Error("Missing or invalid Scramjet assets: "+[...new Set(missing)].join(", "));
  diagLog("SUCCESS","All required Scramjet assets passed preflight checks.");
 }
 async function getWorker(){
  if(!("serviceWorker" in navigator)){const e=new Error("Service workers are unavailable. Open the JSDelivr HTTPS link in a normal browser tab.");diagLog("ERROR",e.message);throw e}
  const scope=BASE_URL.pathname;
  diagLog("INFO",`Registering service worker at ${PATHS.sw} with scope ${scope}`);
  let reg;
  try{reg=await navigator.serviceWorker.register(PATHS.sw,{scope,updateViaCache:"none"});diagLog("SUCCESS",`Service worker registration created (state: ${reg.installing?"installing":reg.waiting?"waiting":reg.active?"active":"unknown"}).`)}
  catch(e){diagLog("ERROR","Service worker registration threw: "+diagFormat(e));throw new Error("Service worker registration failed: "+(e?.message||e)+". The SW file must be in the same JSDelivr folder as index.svg.")}
  let readyReg;
  try{readyReg=await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error("Timed out waiting for navigator.serviceWorker.ready")),15000))]);diagLog("SUCCESS","Service worker is ready.")}
  catch(e){diagLog("ERROR","Service worker did not become ready: "+diagFormat(e));throw e}
  if(!navigator.serviceWorker.controller){
   diagLog("WARN","No active service worker controls this page yet; waiting up to 10 seconds for controllerchange.");
   await Promise.race([
    new Promise(resolve=>navigator.serviceWorker.addEventListener("controllerchange",resolve,{once:true})),
    new Promise((_,reject)=>setTimeout(()=>reject(new Error("Service worker is active but does not control this page yet. Reload once, then retry.")),10000))
   ]).catch(e=>{diagLog("ERROR",diagFormat(e));throw e});
  }
  const sw=navigator.serviceWorker.controller;
  if(!sw||!readyReg.active)throw new Error("Scramjet service worker is not controlling this page. Reload and retry.");
  diagLog("SUCCESS",`Service worker controls this page${sw.scriptURL?`: ${sw.scriptURL}`:""}.`);
  return sw;
 }
 function makePlugins(t){
  return [
   new utils.HttpCachePlugin(),
   new utils.UrlWatcherPlugin(url=>{
    const next=String(url||"");if(!/^https?:\/\//i.test(next))return;
    if(t.url!==next){
     diagLog("INFO",`Proxied URL changed to ${diagRedact(next)}`);
     t.url=next;t.title=host(next);
     if(t.h&&t.i>=0&&t.h[t.i]!==next){t.h=t.h.slice(0,t.i+1);t.h.push(next);t.i++}
     render();
    }
   }),
   new utils.CatchEscapedLinksPlugin(url=>{
    const app=new URL(location.href);app.search="";app.searchParams.set("url",url.href);app.hash="";return app;
   })
  ];
 }
 return {
  get ready(){return state==="ready"},
  async init(){
   if(state==="ready")return;
   if(state==="starting")throw new Error("Engine initialization is already running.");
   state="starting";diagLog("INFO","Scramjet engine initialization started.");
   try{
    await preflight();
    const sw=await getWorker();
    diagLog("INFO","Loading Scramjet controller dependencies.");
    await loadScript(PATHS.bundle);
    await loadScript(PATHS.api);
    await loadScript(PATHS.utils);
    await loadScript(PATHS.libcurl);
    const api=window.$scramjetController;
    utils=window.$scramjetUtils;
    if(!api?.Controller)throw new Error("Scramjet controller bundle did not expose $scramjetController.Controller.");
    if(!utils)throw new Error("Scramjet utilities did not expose $scramjetUtils.");
    if(!window.LibcurlTransport?.LibcurlClient)throw new Error("libcurl transport did not expose LibcurlClient.");
    api.config.injectPath=PATHS.inject;
    api.config.wasmPath=PATHS.wasm;
    api.config.scramjetPath=PATHS.bundle;
    /* Keep proxied routes beneath this repository path so JSDelivr's scoped SW can intercept them. */
    api.config.prefix=new URL("./~/sj/",BASE_URL).pathname;
    diagLog("INFO","Creating WebSocket/Wisp transport.");
    diagLog("DEBUG","Configured Wisp endpoint: "+WISP);
    transport=new window.LibcurlTransport.LibcurlClient({wisp:WISP,websocket:WISP});
    controller=new api.Controller({serviceworker:sw,transport});
    diagLog("INFO","Waiting for Scramjet controller handshake (15-second timeout).");
    await Promise.race([controller.wait(),new Promise((_,reject)=>setTimeout(()=>reject(new Error("Timed out waiting for the Scramjet controller handshake. Check the service-worker logs and controller files.")),15000))]);
    state="ready";say("Scramjet controller ready");
   }catch(e){state="error";diagLog("ERROR","Scramjet initialization failed: "+diagFormat(e));throw e}
  },
  attach(t){
   if(state!=="ready"||!controller){const e=new Error("Scramjet is not ready yet.");diagLog("ERROR",e.message);throw e}
   if(t.sjf)return t.sjf;
   try{t.sjf=controller.createFrame(t.f,{plugins:makePlugins(t)});diagLog("SUCCESS","Scramjet created a proxied frame.");return t.sjf}
   catch(e){diagLog("ERROR","Could not attach Scramjet to the frame: "+diagFormat(e));throw e}
  },
  go(t,u){
   if(state!=="ready")throw new Error("Scramjet is not ready yet.");if(!t.sjf)this.attach(t);
   diagLog("INFO",`Proxy navigation requested: ${diagRedact(u)}`);
   try{const result=t.sjf.go(u);if(result&&typeof result.catch==="function")result.catch(e=>diagLog("ERROR",`Proxy navigation rejected for ${diagRedact(u)}: ${diagFormat(e)}`));return result}
   catch(e){diagLog("ERROR",`Proxy navigation threw for ${diagRedact(u)}: ${diagFormat(e)}`);throw e}
  },
  reload(t){if(t?.sjf)return t.sjf.reload();try{t?.f?.contentWindow?.location.reload()}catch{}},
  currentUrl(t){return t?.url||null},
  title(t){try{return t.f.contentDocument.title||t.title||""}catch{return t?.title||""}}
 };
})();
/* ===== state ===== */
const D={favs:[["Apple","https://www.apple.com","","#e8e8ea"],["iCloud","https://www.icloud.com","☁","#2a8ff7"],["Yahoo","https://www.yahoo.com","!","#6001d2"],["Bing","https://www.bing.com","B","#1b8cf0"],["Google","https://www.google.com","G","#fff"],["Wikipedia","https://www.wikipedia.org","W","#fff"],["Facebook","https://www.facebook.com","f","#1877f2"],["Twitter","https://twitter.com","𝕏","#000"],["YouTube","https://www.youtube.com","▶","#f00"],["Reddit","https://www.reddit.com","R","#ff4500"]],bm:[],hist:[],se:"https://www.google.com/search?q=",tb:1,dev:0,dd:0,dr:0,snd:1,rf:1};
let S;try{S={...D,...JSON.parse(localStorage.sf27)}}catch{S={...D}}
if(typeof S.snd!=="number")S.snd=1;if(typeof S.rf!=="number")S.rf=1;delete S.wn;
const save=()=>{try{localStorage.sf27=JSON.stringify(S)}catch{}};
const $=s=>document.querySelector(s);
const P={back:'<path d="M15 5l-7 7 7 7"/>',fwd:'<path d="M9 5l7 7-7 7"/>',sb:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M9 5v14"/>',share:'<path d="M12 15V4M8 8l4-4 4 4M7 10H6a1 1 0 0 0-1 1v8a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-8a1 1 0 0 0-1-1h-1"/>',plus:'<path d="M12 5v14M5 12h14"/>',tabs:'<rect x="8" y="8" width="12" height="12" rx="3"/><path d="M16 8V7a3 3 0 0 0-3-3H7a3 3 0 0 0-3 3v6a3 3 0 0 0 3 3h1"/>',reload:'<path d="M20 12a8 8 0 1 1-2.6-5.9M20 4v5h-5"/>',more:'<circle cx="5" cy="12" r="1.2"/><circle cx="12" cy="12" r="1.2"/><circle cx="19" cy="12" r="1.2"/>',page:'<rect x="4" y="4" width="16" height="9" rx="2"/><path d="M4 17h10M4 21h6"/>',x:'<path d="M6 6l12 12M18 6L6 18"/>'};
const I=n=>`<svg xmlns="http://www.w3.org/2000/svg" class="icon-svg" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${P[n]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
document.querySelectorAll("[data-i]").forEach(e=>e.innerHTML=I(e.dataset.i));
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

/* ===== Splooshi diagnostics ===== */
const SPL_LOG_KEY="splooshi.diagnostics.v1",SPL_LOG_LIMIT=250;
let SPL_LOGS=[],SPL_LOG_FILTER="all";
try{const prior=JSON.parse(sessionStorage.getItem(SPL_LOG_KEY)||"[]");if(Array.isArray(prior))SPL_LOGS=prior.filter(x=>x&&typeof x.message==="string").slice(-SPL_LOG_LIMIT)}catch{}
function diagRedact(value){
 let text=String(value??"");
 return text.replace(/\b(?:https?|wss?):\/\/[^\s"'<>]+/gi,raw=>{
  try{const trail=(raw.match(/[),.;]+$/)||[""])[0],clean=raw.slice(0,raw.length-trail.length),u=new URL(clean);return u.origin+u.pathname+trail}catch{return raw}
 });
}
function diagFormat(value){
 if(value instanceof Error)return `${value.name||"Error"}: ${value.message||"Unknown error"}${value.stack?"\n"+value.stack:""}`;
 if(typeof value==="string")return value;
 try{return JSON.stringify(value)}catch{return String(value)}
}
function diagPersist(){try{sessionStorage.setItem(SPL_LOG_KEY,JSON.stringify(SPL_LOGS.slice(-SPL_LOG_LIMIT)))}catch{}}
function diagUpdateBadge(){
 const n=SPL_LOGS.filter(x=>x.level==="ERROR").length,b=document.getElementById("logCount"),l=document.getElementById("logLaunch");
 if(b)b.textContent=String(n);if(l){l.classList.toggle("has-errors",n>0);l.title=n?`${n} error${n===1?"":"s"} recorded — open diagnostics`:"Open logs and errors";l.setAttribute("aria-label",n?`Open logs and errors, ${n} recorded`:"Open logs and errors")}
 const settingsCount=document.getElementById("settingsErrorCount");if(settingsCount)settingsCount.textContent=n?`(${n} errors)`:"(no errors)";
}
function diagRender(){
 const list=document.getElementById("logList");if(!list)return;
 const filtered=SPL_LOG_FILTER==="all"?SPL_LOGS:SPL_LOGS.filter(x=>x.level===SPL_LOG_FILTER.toUpperCase());
 list.innerHTML=filtered.length?filtered.map(x=>`<div class="logEntry l-${String(x.level).toLowerCase()}"><span class="logTime">${esc(new Date(x.at).toLocaleTimeString())}</span><span class="logLevel">${esc(x.level)}</span><div class="logMessage">${esc(x.message)}</div></div>`).join(""):'<div class="logEmpty">No messages in this filter.</div>';
 list.scrollTop=list.scrollHeight;
 const errors=SPL_LOGS.filter(x=>x.level==="ERROR").length,warns=SPL_LOGS.filter(x=>x.level==="WARN").length;
 const sum=document.getElementById("logSummary");if(sum)sum.textContent=`${SPL_LOGS.length} entries · ${errors} errors · ${warns} warnings · engine ${typeof Engine!=="undefined"&&Engine.ready?"ready":"not ready"}`;
 diagUpdateBadge();
}
function diagLog(level,message){
 const norm={DEBUG:"DEBUG",INFO:"INFO",WARN:"WARN",WARNING:"WARN",ERROR:"ERROR",SUCCESS:"SUCCESS"},lv=norm[String(level||"INFO").toUpperCase()]||"INFO";
 const entry={at:new Date().toISOString(),level:lv,message:diagRedact(diagFormat(message)).slice(0,6000)};
 SPL_LOGS.push(entry);if(SPL_LOGS.length>SPL_LOG_LIMIT)SPL_LOGS.splice(0,SPL_LOGS.length-SPL_LOG_LIMIT);diagPersist();diagUpdateBadge();
 const panel=document.getElementById("logPanel");if(panel?.classList.contains("o"))diagRender();
}
function diagReportText(){return ["Splooshi diagnostics",`Generated: ${new Date().toISOString()}`,`Page: ${diagRedact(location.href)}`,`Origin: ${location.origin}`,`Secure context: ${!!isSecureContext}`,`Service worker supported: ${!!navigator.serviceWorker}`,`Engine ready: ${typeof Engine!=="undefined"&&Engine.ready}`,"",...SPL_LOGS.map(x=>`[${x.at}] [${x.level}] ${x.message}`)].join("\n")}
function openDiagnostics(){const p=document.getElementById("logPanel");if(!p)return;p.classList.add("o");p.setAttribute("aria-hidden","false");diagRender()}
function closeDiagnostics(){const p=document.getElementById("logPanel");if(!p)return;p.classList.remove("o");p.setAttribute("aria-hidden","true")}
function diagSetStatus(text){const e=document.getElementById("logFooterStatus");if(e)e.textContent=text}
async function diagCopy(){const text=diagReportText();try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw new Error("Clipboard API unavailable");diagSetStatus("Copied to clipboard")}catch{try{const ta=document.createElementNS(HTML_NS,"textarea");ta.value=text;ta.style.cssText="position:fixed;opacity:0;left:-9999px";document.getElementById("svgRoot").appendChild(ta);ta.select();const ok=document.execCommand("copy");ta.remove();diagSetStatus(ok?"Copied to clipboard":"Select Download instead")}catch{diagSetStatus("Copy unavailable — use Download")}}}
function diagDownload(){try{const blob=new Blob([diagReportText()],{type:"text/plain;charset=utf-8"}),u=URL.createObjectURL(blob),a=document.createElementNS(HTML_NS,"a");a.href=u;a.download="splooshi-diagnostics.txt";a.style.display="none";document.getElementById("svgRoot").appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);diagSetStatus("Diagnostics downloaded")}catch(e){diagLog("ERROR","Could not download diagnostics: "+diagFormat(e));diagSetStatus("Download failed")}}
function diagClear(){SPL_LOGS=[];diagPersist();diagLog("INFO","Log history cleared by user.");diagRender();diagSetStatus("Cleared")}
document.getElementById("logLaunch")?.addEventListener("click",openDiagnostics);
document.getElementById("logClose")?.addEventListener("click",closeDiagnostics);
document.getElementById("logPanel")?.addEventListener("pointerdown",e=>{if(e.target===document.getElementById("logPanel"))closeDiagnostics()});
document.getElementById("logCopy")?.addEventListener("click",diagCopy);
document.getElementById("logDownload")?.addEventListener("click",diagDownload);
document.getElementById("logClear")?.addEventListener("click",diagClear);
document.querySelectorAll("[data-log-filter]").forEach(b=>b.addEventListener("click",()=>{SPL_LOG_FILTER=b.dataset.logFilter;document.querySelectorAll("[data-log-filter]").forEach(x=>x.classList.toggle("active",x===b));diagRender()}));
document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==="l"){e.preventDefault();openDiagnostics()}else if(e.key==="Escape"&&document.getElementById("logPanel")?.classList.contains("o"))closeDiagnostics()});
const SPL_ORIGINAL_CONSOLE_ERROR=console.error.bind(console),SPL_ORIGINAL_CONSOLE_WARN=console.warn.bind(console);
console.error=(...args)=>{diagLog("ERROR",args.map(diagFormat).join(" "));SPL_ORIGINAL_CONSOLE_ERROR(...args)};
console.warn=(...args)=>{diagLog("WARN",args.map(diagFormat).join(" "));SPL_ORIGINAL_CONSOLE_WARN(...args)};
window.addEventListener("error",e=>{const at=e.filename?` (${diagRedact(e.filename)}:${e.lineno||0}:${e.colno||0})`:"";diagLog("ERROR",`Uncaught script error: ${e.message||"Unknown error"}${at}${e.error?.stack?"\n"+e.error.stack:""}`)});
window.addEventListener("unhandledrejection",e=>diagLog("ERROR","Unhandled promise rejection: "+diagFormat(e.reason)));
window.addEventListener("online",()=>diagLog("SUCCESS","Browser reports network connection restored."));
window.addEventListener("offline",()=>diagLog("WARN","Browser reports offline status."));
if(navigator.serviceWorker){
 navigator.serviceWorker.addEventListener("controllerchange",()=>diagLog("SUCCESS","Service worker controller changed for this page."));
 navigator.serviceWorker.addEventListener("message",e=>{const d=e.data&&e.data.__splooshiLog;if(d)diagLog(d.level||"INFO","[Service Worker] "+(d.message||"Diagnostic message"))});
}
diagLog("INFO","Diagnostics initialized. Ctrl/⌘ + Shift + L opens this panel.");
diagLog("DEBUG",`Environment: ${location.origin}; secure context=${!!isSecureContext}; service workers=${!!navigator.serviceWorker}`);

const host=u=>{try{return new URL(u).hostname.replace(/^www\./,"")}catch{return u}};
const norm=s=>{s=s.trim();if(!s)return"";if(/^[a-z][a-z0-9+.-]*:\/\//i.test(s))return s;if(/^(localhost|[\w-]+(\.[\w-]+)+)(:\d+)?(\/.*)?$/i.test(s))return"https://"+s;return S.se+encodeURIComponent(s)};
function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("o");clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove("o"),1800)}
/* Tiny synthesized glass sounds: no downloaded audio, no autoplay before a gesture. */
let audioContext=null,lastSoundAt=0;
function uiSound(kind="tap"){
 if(Number(S.snd)!==1)return;
 const nowMs=Date.now();if(nowMs-lastSoundAt<42)return;lastSoundAt=nowMs;
 try{
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
  audioContext ||= new AC();if(audioContext.state==="suspended")audioContext.resume();
  const now=audioContext.currentTime;
  const tones=kind==="success"?[[880,0],[1174.66,.055]]:kind==="close"?[[610,0],[420,.035]]:kind==="navigate"?[[660,0],[990,.045]]:[[820,0]];
  for(const [hz,delay] of tones){
   const osc=audioContext.createOscillator(),gain=audioContext.createGain();
   osc.type="sine";osc.frequency.setValueAtTime(hz,now+delay);osc.frequency.exponentialRampToValueAtTime(Math.max(120,hz*(kind==="close"?.78:1.12)),now+delay+.075);
   gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.026,now+delay+.009);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.105);
   osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+delay);osc.stop(now+delay+.115);
  }
 }catch{}
}
/* One quiet click for normal controls; typing into the address field stays silent. */
document.addEventListener("click",e=>{const b=e.target.closest("button,.ib,.tab,.f");if(b&&!b.disabled)uiSound("tap")},true);
/* ===== tabs ===== */
let tabs=[],cur;
function mk(url){const t={id:Math.random(),url:"",title:"",h:[],i:-1,z:1};tabs.push(t);cur=t;if(url)go(t,url);else render();return t}
function frame(t){const f=htmlEl("iframe");f.allow="fullscreen;autoplay;clipboard-write;encrypted-media";f.onload=()=>loaded(t);f.onerror=()=>diagLog("ERROR","Proxy iframe emitted an error event for "+diagRedact(t.url||"about:blank"));t.f=f;$("#views").append(f);try{Engine.attach(t)}catch(e){diagLog("ERROR","Proxy frame setup failed: "+diagFormat(e));throw e}zoom(t)}
function go(t,u,push=true){u=norm(u);if(!u)return;diagLog("INFO","Navigation input: "+diagRedact(u));uiSound("navigate");try{if(push){t.h=t.h.slice(0,t.i+1);t.h.push(u);t.i++}t.url=u;t.title=host(u);if(!Engine.ready){t.pendingUrl=u;diagLog("INFO","Navigation queued until Scramjet is ready.");render();return}delete t.pendingUrl;if(!t.f)frame(t);Engine.go(t,u);render()}catch(e){diagLog("ERROR","Navigation failed for "+diagRedact(u)+": "+diagFormat(e));toast("Navigation failed — open Logs");openDiagnostics()}}
function loaded(t){try{const doc=t.f?.contentDocument,body=(doc?.body?.innerText||"").trim();if(/^Internal Service Worker Error:/i.test(body))diagLog("ERROR","Proxy returned a service-worker error page: "+body.slice(0,900));const u=Engine.currentUrl(t);if(u&&u!==t.url){t.url=u;t.h=t.h.slice(0,t.i+1);t.h.push(u);t.i++}const n=Engine.title(t);t.title=n||host(t.url);if(t.url){diagLog("SUCCESS","Frame load event received for "+diagRedact(t.url));if(!S.hist[0]||S.hist[0].u!==t.url)S.hist.unshift({u:t.url,t:t.title,d:Date.now()});S.hist=S.hist.slice(0,300);save()}}catch(e){diagLog("WARN","Frame load completed, but page details could not be read: "+diagFormat(e))}render()}
function back(){const t=cur;if(t.i>0){t.i--;go(t,t.h[t.i],false)}else if(t.i==0){t.i=-1;t.url="";t.title="";render()}}
function fwd(){const t=cur;if(t.i<t.h.length-1){t.i++;go(t,t.h[t.i],false)}}
function close(t){const k=tabs.indexOf(t);t.f&&t.f.remove();tabs.splice(k,1);if(!tabs.length)mk();else if(cur===t)cur=tabs[Math.min(k,tabs.length-1)];render()}
function zoom(t){if(!t.f)return;t.f.style.width=100/t.z+"%";t.f.style.height=100/t.z+"%";t.f.style.transform=`scale(${t.z})`}
const label=t=>t.url?(t.title||host(t.url)):"Start Page";
function fav(t){const c=t.url?"#"+(Math.abs([...host(t.url)].reduce((a,c)=>a*31+c.charCodeAt(0)|0,7))%0xffffff).toString(16).padStart(6,"0"):"";return t.url?`<i class="fav" style="background:${c}">${esc((host(t.url)[0]||"").toUpperCase())}</i>`:`<span style="font-size:13px">☆</span>`}
/* ===== render ===== */
function render(){
 const t=cur,bc=$("#svgRoot").classList;
 $("#dev").style.setProperty("--off",(bc.contains("portrait")?0:bc.contains("landscape")?46+(S.tb?44:0):60)+"px");
