function cloakProxy(){
 const target=location.href;
 const w=window.open("about:blank","_blank");
 if(!w)return toast("Allow pop-ups to cloak the proxy");
 try{
  const d=w.document;
  d.title="Google Drive";
  d.documentElement.style.cssText="margin:0;width:100%;height:100%;background:#fff";
  d.body.style.cssText="margin:0;width:100%;height:100%;overflow:hidden";
  const f=d.createElement("iframe");
  f.title="Cloaked proxy";f.referrerPolicy="no-referrer";
  f.allow="fullscreen;autoplay;clipboard-write;encrypted-media";
  f.style.cssText="display:block;border:0;width:100%;height:100%;background:#fff";
  f.src=target;
  d.body.appendChild(f);
  toast("Proxy opened in about:blank");
 }catch(err){try{w.close()}catch{}toast("Could not cloak the proxy");}
}
function cloakPage(url=cur?.url){
 if(!url)return toast("Open a website first");
 const w=window.open("about:blank","_blank");
 if(!w)return toast("Allow pop-ups to use Cloak");
 try{
  w.document.title="Google Docs";
  w.document.documentElement.style.cssText="margin:0;width:100%;height:100%;background:#fff";
  w.document.body.style.cssText="margin:0;width:100%;height:100%;overflow:hidden";
  const f=w.document.createElement("iframe");
  f.title="Cloaked page";f.referrerPolicy="no-referrer";
  f.allow="fullscreen;autoplay;clipboard-write;encrypted-media";
  f.style.cssText="display:block;border:0;width:100%;height:100%;background:#fff";
  w.document.body.appendChild(f);
  // Route the cloaked frame through the same engine adapter used by normal tabs.
  // Once Engine is backed by Scramjet, this uses Scramjet's proxied navigation too.
  const cloakTab={id:Math.random(),url:"",title:host(url),h:[],i:-1,z:1,f};
  Engine.attach(cloakTab);
  Engine.go(cloakTab,url);
 }catch(err){try{w.close()}catch{}toast("Could not open the cloaked page");}
}
