document.addEventListener("pointermove",e=>{
 pointerSample=e;if(pointerRAF)return;
 pointerRAF=requestAnimationFrame(()=>{
  pointerRAF=0;
  const dev=$("#dev"),scale=dev?.getBoundingClientRect().width/(dev?.offsetWidth||1)||1;
  document.querySelectorAll(GS).forEach(g=>{
   const r=g.getBoundingClientRect();if(!r.width||!r.height)return;
   const x=pointerSample.clientX,y=pointerSample.clientY;
   const dx=Math.max(r.left-x,0,x-r.right),dy=Math.max(r.top-y,0,y-r.bottom);
   const distance=Math.hypot(dx,dy),k=Math.max(0,Math.min(1,1-distance/190));
   const eased=k*k*(3-2*k);
   g.style.setProperty("--pi",eased.toFixed(3));
   g.style.setProperty("--mx",((x-r.left)/scale)+"px");
   g.style.setProperty("--my",((y-r.top)/scale)+"px");
  });
 });
});
$("#svgRoot").addEventListener("mouseleave",clearGlassGlow);
document.addEventListener("pointerup",e=>{if(e.pointerType!=="mouse")clearGlassGlow()});

/* boot: render the browser UI before any network-dependent engine startup. */
mk();
emu();
mode();
diagLog("INFO","Splooshi interface rendered; starting proxy engine independently.");
(async()=>{
 try{
  await Engine.init();toast("Splooshi is online");diagLog("SUCCESS","Splooshi startup complete; proxy engine is ready.");
  for(const t of tabs){if(t.pendingUrl){const u=t.pendingUrl;delete t.pendingUrl;go(t,u,false)}}
 }catch(e){console.error("[Splooshi] Startup failed",e);toast("Proxy offline — open Logs");setTimeout(openDiagnostics,80)}
 const q=new URLSearchParams(location.search).get("url");if(q&&Engine.ready)go(cur,q)
})();
